"""Enumerating the Python source files of a project."""
import os

_SKIPPED_DIRECTORIES = {"__pycache__", "node_modules", "site-packages"}


def project_files(root):
    """Absolute paths of the `.py` files under `root`, in a stable order.

    Hidden directories, caches and virtual environments are skipped.
    """
    root = os.path.abspath(root)
    for directory, subdirectories, files in os.walk(root):
        subdirectories[:] = sorted(
            name for name in subdirectories
            if not name.startswith(".") and name not in _SKIPPED_DIRECTORIES
            and not os.path.isfile(os.path.join(directory, name, "pyvenv.cfg")))
        for name in sorted(files):
            if name.endswith(".py"):
                yield os.path.join(directory, name)
"""Lazily-described completion candidates.

An entry stands for whatever a name refers to; its value and description are
only computed when the name survives prefix filtering.
"""
from .describe import (
    describe_class,
    describe_function,
    describe_module,
    describe_param,
    describe_value,
)

_UNSET = object()


class BindingEntry:
    """A name bound by a statement in parsed source."""

    def __init__(self, binding, inferrer):
        self.binding = binding
        self.inferrer = inferrer

    def value(self):
        return self.inferrer.infer_binding(self.binding)

    def describe(self, name):
        kind = self.binding.kind
        if kind == "param":
            return describe_param(name)
        if kind == "def":
            return describe_function(name)
        if kind == "class":
            return describe_class(name)
        if kind == "import":
            return describe_module(name)
        return describe_value(name, self.value())


class ValueEntry:
    """A name whose value is produced on demand by a factory."""

    def __init__(self, factory):
        self._factory = factory
        self._value = _UNSET

    def value(self):
        if self._value is _UNSET:
            try:
                self._value = self._factory()
            except Exception:
                self._value = None
        return self._value

    def describe(self, name):
        return describe_value(name, self.value())
"""Formatting of completion `type` and `description` fields."""
from .values import CLASS, FUNCTION, INSTANCE, MODULE

STATEMENT = "statement"
PARAM = "param"
KEYWORD = "keyword"


def describe_value(name, value):
    """(type, description) for a name bound to an inferred value (or None)."""
    if value is None:
        return STATEMENT, STATEMENT
    if value.kind == MODULE:
        return MODULE, f"module {name}"
    if value.kind == CLASS:
        return CLASS, f"class {name}"
    if value.kind == FUNCTION:
        return FUNCTION, f"def {name}(...)"
    if value.kind == INSTANCE and value.type_name:
        return INSTANCE, f"instance of {value.type_name}"
    return STATEMENT, STATEMENT


def describe_function(name):
    return FUNCTION, f"def {name}(...)"


def describe_class(name):
    return CLASS, f"class {name}"


def describe_module(name):
    return MODULE, f"module {name}"


def describe_param(name):
    return PARAM, f"param {name}"


def describe_keyword(name):
    return KEYWORD, name
"""The completion engine: ties context, parsing, scopes and inference together."""
import ast
import os
from dataclasses import asdict, dataclass

from . import context as cursor_context
from .builtin_scope import KEYWORDS
from .describe import describe_keyword, describe_module
from .inference import Inferrer
from .locate import find_scope
from .matching import make_matcher
from .members import is_public
from .modules import Importer, ModuleContext
from .parsing import parse_tolerant
from .ranking import sort_keywords, sort_names
from .source import load_document
from .values import MODULE


class ModuleEntry:
    """A module name offered inside an import statement."""

    def describe(self, name):
        return describe_module(name)


@dataclass
class Completion:
    name: str
    complete: str
    type: str
    description: str

    def to_dict(self):
        return asdict(self)


def complete_file(path, line, col, fuzzy=False, project=None):
    """Completions for the cursor at 1-based `line`, 0-based `col` of `path`."""
    document = load_document(path)
    document.check_position(line, col)
    return Completer(document, line, col, fuzzy, project).run()


class Completer:
    def __init__(self, document, line, col, fuzzy, project=None):
        self.document = document
        self.line = line
        self.col = col
        self.fuzzy = fuzzy
        self.project = project

    def run(self):
        text_before = self.document.text_before(self.line, self.col)
        import_request = cursor_context.analyze_import(text_before)
        request = import_request or cursor_context.analyze(text_before)
        if request.kind in (cursor_context.NONE, cursor_context.IMPORT_NOTHING):
            return []

        importer = Importer(os.path.abspath(self.project or self.document.directory))
        tree = parse_tolerant(self.document.text, cursor=(self.line, self.col))
        module = ModuleContext(self.document.path, "__main__", tree, self.document.text)
        importer.register(module)
        inferrer = Inferrer(importer)

        if import_request is not None:
            entries, keywords = self._import_entries(inferrer, module, import_request)
        elif request.kind == cursor_context.ATTRIBUTE:
            scope = find_scope(module, self.line, self.col, self.document.lines[self.line - 1])
            entries = self._attribute_entries(inferrer, scope, request.receiver)
            keywords = []
        else:
            scope = find_scope(module, self.line, self.col, self.document.lines[self.line - 1])
            entries = inferrer.visible_entries(scope, self.line)
            keywords = KEYWORDS
        return self._results(entries, keywords, request.prefix)

    def _results(self, entries, keywords, prefix):
        matches = make_matcher(prefix, self.fuzzy)
        cut = len(prefix)
        results = []
        for name in sort_names(n for n in entries if matches(n)):
            kind, description = entries[name].describe(name)
            results.append(Completion(name, name[cut:], kind, description))
        for name in sort_keywords(k for k in keywords if matches(k)):
            kind, description = describe_keyword(name)
            results.append(Completion(name, name[cut:], kind, description))
        return results

    def _import_entries(self, inferrer, context, request):
        """(entries, keywords) for a cursor inside an import statement."""
        importer = inferrer.importer
        if request.kind == cursor_context.IMPORT_KEYWORD:
            return {}, ["import"]
        if request.kind == cursor_context.IMPORT_MODULE:
            if request.level:
                package = importer.import_relative(context, request.module, request.level)
                names = importer.submodule_names(package)
            elif request.module:
                names = importer.submodule_names(importer.import_absolute(request.module))
            else:
                names = importer.top_level_names()
            return {name: ModuleEntry() for name in names}, []
        source = importer.import_module(context, request.module, request.level)
        if source is None or source.kind != MODULE:
            return {}, []
        return inferrer.members.exported(source, submodules=True), []

    def _attribute_entries(self, inferrer, scope, receiver):
        try:
            expression = ast.parse(receiver.strip(), mode="eval").body
        except (SyntaxError, ValueError):
            return {}
        line_text = self.document.lines[self.line - 1]
        position = (self.line, len(line_text[:self.col].encode("utf-8")))
        entries = {}
        for value in inferrer.infer_values(expression, scope, pos=position, strict=True):
            members = inferrer.members.all(value)
            if value.kind == MODULE:
                members = {name: entry for name, entry in members.items() if is_public(name)}
            for name, entry in members.items():
                entries.setdefault(name, entry)
        return entries
"""Exception types used across sith."""


class SithError(Exception):
    """A user-facing error: reported on STDERR and turned into exit code 1."""
"""Prefix and fuzzy matching of completion names."""


def prefix_match(prefix, name):
    return name.lower().startswith(prefix.lower())


def fuzzy_match(query, name):
    """True when the characters of `query` appear in `name` in order."""
    remaining = iter(name.lower())
    return all(char in remaining for char in query.lower())


def make_matcher(prefix, fuzzy):
    if not prefix:
        return lambda name: True
    if fuzzy:
        return lambda name: fuzzy_match(prefix, name)
    return lambda name: prefix_match(prefix, name)
"""Ordering of completion results."""


def name_group(name):
    """0 for public names, 1 for private (`_x`), 2 for dunders (`__x__`)."""
    if name.startswith("__") and name.endswith("__"):
        return 2
    if name.startswith("_"):
        return 1
    return 0


def sort_names(names):
    return sorted(names, key=lambda name: (name_group(name), name.lower(), name))


def sort_keywords(keywords):
    return sorted(keywords, key=lambda name: (name.lower(), name))
"""Loading source documents and validating cursor positions."""
import os
from dataclasses import dataclass, field

from .errors import SithError


@dataclass
class Document:
    """A source file split into lines, with cursor-related helpers."""

    path: str
    text: str
    lines: list = field(default_factory=list)

    @property
    def directory(self):
        return os.path.dirname(os.path.abspath(self.path))

    def check_position(self, line, col):
        """Validate a 1-based line and 0-based column."""
        if line < 1 or line > len(self.lines):
            raise SithError(f"line {line} is out of range (file has {len(self.lines)} lines)")
        length = len(self.lines[line - 1])
        if col < 0 or col > length:
            raise SithError(f"column {col} is out of range (line {line} has {length} characters)")

    def text_before(self, line, col):
        """All source text preceding the cursor."""
        return "\n".join(self.lines[: line - 1] + [self.lines[line - 1][:col]])


def normalize_newlines(text):
    return text.replace("\r\n", "\n").replace("\r", "\n")


def read_text(path):
    """Read a file as UTF-8 text, raising SithError on any problem."""
    if not os.path.exists(path):
        raise SithError(f"file not found: {path}")
    if not os.path.isfile(path):
        raise SithError(f"not a regular file: {path}")
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except OSError as exc:
        raise SithError(f"cannot read {path}: {exc}") from exc
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise SithError(f"file is not valid UTF-8: {path}") from exc
    if text.startswith("\ufeff"):
        text = text[1:]
    return normalize_newlines(text)


def load_document(path):
    text = read_text(path)
    return Document(path=path, text=text, lines=text.split("\n"))

