                return None
            module = self.local_submodule(module, part)
        return module

    def import_module(self, context, dotted, level=0):
        if level:
            return self.import_relative(context, dotted, level)
        return self.import_absolute(dotted)

    def within_project(self, directory):
        return _within(directory, self.project_dir)

    # -- stubs ----------------------------------------------------------------------

    def stub_for(self, context):
        """The parsed `.pyi` stub giving type information for the module `context`, or None.

        An adjacent `foo.pyi` wins over `stubs/foo.pyi` and `stubs/foo/__init__.pyi`.
        """
        if context is None or not context.path or context.is_stub:
            return None
        if context.path not in self._stubs:
            self._stubs[context.path] = None
            path = self._stub_path(context.path)
            stub = self.context_for_file(path) if path else None
            if stub is not None:
                self._sources.setdefault(stub.path, context)
            self._stubs[context.path] = stub
        return self._stubs[context.path]

    def _stub_path(self, path):
        adjacent = os.path.splitext(path)[0] + ".pyi"
        if os.path.isfile(adjacent):
            return adjacent
        name = self.module_name(path)
        if not name:
            return None
        base = os.path.join(self.stub_dir, *name.split("."))
        for candidate in (base + ".pyi", os.path.join(base, "__init__.pyi")):
            if os.path.isfile(candidate):
                return candidate
        return None

    def source_for(self, stub):
        """The `.py` module a stub describes, or None for stub-only modules."""
        if stub is None or not stub.is_stub:
            return None
        if stub.path not in self._sources:
            self._sources[stub.path] = None
            path = os.path.splitext(stub.path)[0] + ".py"
            if not os.path.isfile(path):
                path = None
                if _within(stub.path, self.stub_dir):
                    path = self._source_path(self.module_name(stub.path))
            source = self.context_for_file(path) if path else None
            if source is not None and self.stub_for(source) is not stub:
                source = None
            self._sources[stub.path] = source
        return self._sources[stub.path]

    def _source_path(self, dotted):
        if not dotted:
            return None
        base = os.path.join(self.project_dir, *dotted.split("."))
        for candidate in (os.path.join(base, "__init__.py"), base + ".py"):
            if os.path.isfile(candidate):
                return candidate
        return None

    def package_at(self, directory):
        """The package whose directory is `directory` (regular or namespace)."""
        init = _package_init(directory)
        if init:
            context = self.context_for_file(init)
            return LocalModule(context) if context else None
        if os.path.isdir(directory):
            return LocalModule(self.namespace_for(directory))
        return None

    def local_submodule(self, module_value, name):
        """A submodule `name` of a local package, if such a file or directory exists."""
        context = module_value.context
        if not context.is_package or not name:
            return None
        found = _locate(context.directory, name, namespace=False)
        return self._local(found or _locate(context.directory, name, namespace=True))

    def runtime_submodule(self, module_value, name):
        if not hasattr(module_value.obj, "__path__"):
            return None
        return self._import_runtime(f"{module_value.obj.__name__}.{name}")

    # -- listing modules (import completion) ------------------------------------

    def top_level_names(self):
        """Names of every importable top-level module."""
        return set(_module_names(self.project_dir)) | set(_module_names(self.stub_dir)) | available_stdlib()

    def submodule_names(self, module):
        """Names of the submodules of a package value."""
        if isinstance(module, LocalModule):
            if not module.context.is_package:
                return set()
            return set(_module_names(module.context.directory))
        if isinstance(module, RuntimeModule):
            paths = getattr(module.obj, "__path__", None)
            if paths is None:
                return set()
            try:
                return {info.name for info in pkgutil.iter_modules(list(paths))}
            except Exception:
                return set()
        return set()

    def _import_runtime(self, dotted):
        if dotted.split(".")[0] not in STDLIB_NAMES:
            return None
        if dotted not in self._runtime:
            module = None
            try:
                with warnings.catch_warnings(), contextlib.redirect_stdout(io.StringIO()):
                    warnings.simplefilter("ignore")
                    module = importlib.import_module(dotted)
            except BaseException:  # importing arbitrary modules may fail in any way
                module = None
            self._runtime[dotted] = RuntimeModule(module) if module is not None else None
        return self._runtime[dotted]


_STDLIB_AVAILABLE = None


def _within(path, directory):
    path = os.path.abspath(path)
    directory = os.path.abspath(directory)
    return path == directory or path.startswith(directory.rstrip(os.sep) + os.sep)


def available_stdlib():
    """Top-level standard library modules that exist in this runtime."""
    global _STDLIB_AVAILABLE
    if _STDLIB_AVAILABLE is None:
        names = set()
        for name in STDLIB_NAMES:
            if name == "__main__":
                continue
            try:
                if name in sys.modules or importlib.util.find_spec(name) is not None:
                    names.add(name)
            except Exception:
                continue
        _STDLIB_AVAILABLE = names
    return _STDLIB_AVAILABLE


def _locate(directory, name, namespace):
    """("file", path) or ("namespace", directory) for module `name` inside `directory`.

    Regular packages win over modules, and source modules over stub-only
    modules; namespace packages are only considered when `namespace` is true.
    """
    if not name or not os.path.isdir(directory):
        return None
    candidate = os.path.join(directory, name)
    if namespace:
        if os.path.isdir(candidate) and name.isidentifier():
            return "namespace", candidate
        return None
    init = _package_init(candidate)
    if init:
        return "file", init
    for suffix in (".py", ".pyi"):
        if os.path.isfile(candidate + suffix):
            return "file", candidate + suffix
    return None


def _module_names(directory):
    """Names of the modules and packages (including namespace packages) in `directory`."""
    try:
        entries = os.listdir(directory)
    except OSError:
        return []
    names = []
    for entry in entries:
        path = os.path.join(directory, entry)
        if entry.endswith((".py", ".pyi")) and os.path.isfile(path):
            stem = os.path.splitext(entry)[0]
            if stem.isidentifier() and stem != "__init__":
                names.append(stem)
        elif os.path.isdir(path) and entry.isidentifier() and entry != "__pycache__":
            names.append(entry)
    return names


def _package_init(directory):
    for name in ("__init__.py", "__init__.pyi"):
        init = os.path.join(directory, name)
        if os.path.isfile(init):
            return init
    return None
"""Textual analysis of the cursor position: prefix and completion kind."""
import re
from dataclasses import dataclass

NAME = "name"
ATTRIBUTE = "attribute"
NONE = "none"

_OPENERS = {")": "(", "]": "[", "}": "{"}
_STRING_PREFIX_CHARS = "rRbBuUfF"


@dataclass
class CursorContext:
    """What kind of completion is requested and what has been typed so far."""

    kind: str
    prefix: str = ""
    receiver: str = ""


def is_identifier_char(char):
    return char == "_" or char.isalnum()


def analyze(text_before_cursor):
    """Classify the completion request from the source text before the cursor."""
    end = len(text_before_cursor)
    start = end
    while start > 0 and is_identifier_char(text_before_cursor[start - 1]):
        start -= 1
    prefix = text_before_cursor[start:]
    if prefix and prefix[0].isdigit():
        return CursorContext(NONE, prefix)

    before = text_before_cursor[:start]
    if not before.endswith("."):
        return CursorContext(NAME, prefix)

    receiver = extract_receiver(before[:-1])
    if not receiver or receiver.isdigit() or receiver.endswith("."):
        return CursorContext(NONE, prefix)
    return CursorContext(ATTRIBUTE, prefix, receiver)


def extract_receiver(text):
    """Return the expression text that ends at the end of `text`, or None."""
    i = len(text)
    while i > 0:
        char = text[i - 1]
        if char in _OPENERS:
            opener = _match_open(text, i - 1)
            if opener is None:
                return None
            i = opener
            continue
        if is_identifier_char(char):
            while i > 0 and is_identifier_char(text[i - 1]):
                i -= 1
            if i > 0 and text[i - 1] == ".":
                i -= 1
                continue
            break
        if char in "\"'":
            start = _string_start(text, i - 1)
            if start is None:
                return None
            i = start
            while i > 0 and text[i - 1] in _STRING_PREFIX_CHARS:
                i -= 1
            break
        break
    return text[i:].strip()


def _match_open(text, close_index):
    """Index of the bracket opening the one at `close_index`, scanning backwards."""
    stack = [text[close_index]]
    i = close_index - 1
    while i >= 0:
        char = text[i]
        if char in "\"'":
            start = _string_start(text, i)
            if start is None:
                return None
            i = start - 1
            continue
        if char in _OPENERS:
            stack.append(char)
        elif char in "([{":
            if _OPENERS[stack[-1]] != char:
                return None
            stack.pop()
            if not stack:
                return i
        i -= 1
    return None


def _string_start(text, end_index):
    """Index of the opening quote of the string literal ending at `end_index`."""
    quote = text[end_index]
    if end_index >= 2 and text[end_index - 2:end_index + 1] == quote * 3:
        start = text.rfind(quote * 3, 0, end_index - 2)
        return None if start < 0 else start
    i = end_index - 1
    while i >= 0:
        if text[i] == quote and (i == 0 or text[i - 1] != "\\"):
            return i
        if text[i] == "\n":
            return None
        i -= 1
    return None


# -- import statements --------------------------------------------------------------

IMPORT_MODULE = "import-module"
IMPORT_NAME = "import-name"
IMPORT_KEYWORD = "import-keyword"
IMPORT_NOTHING = "import-nothing"

_STATEMENT_START = re.compile(r"\s*(?:from|import)\b")
_DOTTED = r"((?:\w+\s*\.\s*)*)(\w*)"
_IMPORT = re.compile(r"\s*import\s+(.*)", re.S)
_FROM = re.compile(r"\s*from\s+(.*)", re.S)
_FROM_NAMES = re.compile(r"(\.*)\s*([\w.\s]*?)\s*\bimport\s+(.*)", re.S)
_FROM_KEYWORD = re.compile(r"(\.*)\s*(\w+(?:\s*\.\s*\w+)*|)\s+(\w*)", re.S)
_FROM_MODULE = re.compile(r"(\.*)\s*" + _DOTTED, re.S)
_ITEM = re.compile(_DOTTED, re.S)
_NAME = re.compile(r"(\w*)")


@dataclass
class ImportContext:
    """A cursor inside an import statement.

    `module` is the dotted module (relative to `level` leading dots) whose
    submodules or names are completed; `prefix` is what has been typed.
    """

    kind: str
    prefix: str = ""
    module: str = ""
    level: int = 0


def analyze_import(text_before_cursor):
    """An ImportContext when the cursor is inside an import statement, else None."""
    statement = _import_statement(text_before_cursor)
    if statement is None:
        return None
    if re.fullmatch(r"\s*(?:import|from)", statement):
        return None  # still typing the keyword itself
    match = _IMPORT.fullmatch(statement)
    if match:
        item = match.group(1).split(",")[-1].lstrip()
        found = _ITEM.fullmatch(item)
        if not found:
            return ImportContext(IMPORT_NOTHING)
        return ImportContext(IMPORT_MODULE, found.group(2), _dotted(found.group(1)))
    match = _FROM.fullmatch(statement)
    if not match:
        return ImportContext(IMPORT_NOTHING)
    rest = match.group(1)
    found = _FROM_NAMES.fullmatch(rest)
    if found and (found.group(1) or found.group(2).strip()):
        module = re.sub(r"\s+", "", found.group(2))
        item = found.group(3).split(",")[-1].strip()
        name = _NAME.fullmatch(item)
        if not name or not (module.replace(".", "").isidentifier() or not module):
            return ImportContext(IMPORT_NOTHING)
        return ImportContext(IMPORT_NAME, name.group(1), module, len(found.group(1)))
    found = _FROM_KEYWORD.fullmatch(rest)
    if found and (found.group(1) or found.group(2)):
        return ImportContext(IMPORT_KEYWORD, found.group(3))
    found = _FROM_MODULE.fullmatch(rest)
    if found:
        return ImportContext(IMPORT_MODULE, found.group(3), _dotted(found.group(2)),
                             len(found.group(1)))
    return ImportContext(IMPORT_NOTHING)


def _dotted(text):
    """`a . b .` -> `a.b`."""
    return ".".join(part for part in re.sub(r"\s+", "", text).split(".") if part)


def _import_statement(text):
    """The text of the import statement the cursor is in, joined onto one line, or None."""
    lines = text.split("\n")
    current = len(lines) - 1
    lines[current] = _last_simple_statement(lines[current])
    for start in range(current, max(-1, current - 100), -1):
        if _STATEMENT_START.match(lines[start]):
            if not _continues(lines[start:current]):
                return None
            joined = " ".join(_code(line).rstrip().rstrip("\\") for line in lines[start:current])
            joined = (joined + " " + lines[current]) if start < current else lines[current]
            return joined.replace("(", " ").replace(")", " ")
    return None


def _code(line):
    """`line` without a trailing comment."""
    quote = None
    for index, char in enumerate(line):
        if quote:
            if char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char == "#":
            return line[:index]
    return line


def _last_simple_statement(line):
    """The part of `line` after its last top-level `;`."""
    depth = 0
    quote = None
    start = 0
    for index, char in enumerate(line):
        if quote:
            if char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char in "([{":
            depth += 1
        elif char in ")]}":
            depth -= 1
        elif char == ";" and depth <= 0:
            start = index + 1
    return line[start:]


def _continues(lines):
    """True when each of `lines` continues onto the next (open bracket or backslash)."""
    depth = 0
    for line in lines:
        code = _code(line)
        depth += code.count("(") - code.count(")")
        if depth <= 0 and not code.rstrip().endswith("\\"):
            return False
    return True

