"""Enumerating the Python source files of a project."""
import os

_SKIPPED_DIRECTORIES = {"__pycache__", "node_modules", "site-packages"}


def project_files(root):
    """Absolute paths of the `.py` files under `root`, in a stable order.

    Hidden directories, caches and virtual environments are skipped.
    """
    root = os.path.abspath(root)
    for directory, subdirectories, files in os.walk(root):
        subdirectories[:] = sorted(
            name for name in subdirectories
            if not name.startswith(".") and name not in _SKIPPED_DIRECTORIES
            and not os.path.isfile(os.path.join(directory, name, "pyvenv.cfg")))
        for name in sorted(files):
            if name.endswith(".py"):
                yield os.path.join(directory, name)
"""Lazily-described completion candidates.

An entry stands for whatever a name refers to; its value and description are
only computed when the name survives prefix filtering.
"""
from .describe import (
    describe_class,
    describe_function,
    describe_module,
    describe_param,
    describe_value,
)

_UNSET = object()


class BindingEntry:
    """A name bound by a statement in parsed source."""

    def __init__(self, binding, inferrer):
        self.binding = binding
        self.inferrer = inferrer

    def value(self):
        return self.inferrer.infer_binding(self.binding)

    def describe(self, name):
        kind = self.binding.kind
        if kind == "param":
            return describe_param(name)
        if kind == "def":
            return describe_function(name)
        if kind == "class":
            return describe_class(name)
        if kind == "import":
            return describe_module(name)
        return describe_value(name, self.value())


class ValueEntry:
    """A name whose value is produced on demand by a factory."""

    def __init__(self, factory):
        self._factory = factory
        self._value = _UNSET

    def value(self):
        if self._value is _UNSET:
            try:
                self._value = self._factory()
            except Exception:
                self._value = None
        return self._value

    def describe(self, name):
        return describe_value(name, self.value())
"""Formatting of completion `type` and `description` fields."""
from .values import CLASS, FUNCTION, INSTANCE, MODULE

STATEMENT = "statement"
PARAM = "param"
KEYWORD = "keyword"


def describe_value(name, value):
    """(type, description) for a name bound to an inferred value (or None)."""
    if value is None:
        return STATEMENT, STATEMENT
    if value.kind == MODULE:
        return MODULE, f"module {name}"
    if value.kind == CLASS:
        return CLASS, f"class {name}"
    if value.kind == FUNCTION:
        return FUNCTION, f"def {name}(...)"
    if value.kind == INSTANCE and value.type_name:
        return INSTANCE, f"instance of {value.type_name}"
    return STATEMENT, STATEMENT


def describe_function(name):
    return FUNCTION, f"def {name}(...)"


def describe_class(name):
    return CLASS, f"class {name}"


def describe_module(name):
    return MODULE, f"module {name}"


def describe_param(name):
    return PARAM, f"param {name}"


def describe_keyword(name):
    return KEYWORD, name
"""The completion engine: ties context, parsing, scopes and inference together."""
import ast
import os
from dataclasses import asdict, dataclass

from . import context as cursor_context
from .builtin_scope import KEYWORDS
from .describe import describe_keyword, describe_module
from .inference import Inferrer
from .locate import find_scope
from .matching import make_matcher
from .members import is_public
from .modules import Importer, ModuleContext
from .parsing import parse_tolerant
from .ranking import sort_keywords, sort_names
from .source import load_document
from .values import MODULE


class ModuleEntry:
    """A module name offered inside an import statement."""

    def describe(self, name):
        return describe_module(name)


@dataclass
class Completion:
    name: str
    complete: str
    type: str
    description: str

    def to_dict(self):
        return asdict(self)


def complete_file(path, line, col, fuzzy=False, project=None):
    """Completions for the cursor at 1-based `line`, 0-based `col` of `path`."""
    document = load_document(path)
    document.check_position(line, col)
    return Completer(document, line, col, fuzzy, project).run()


class Completer:
    def __init__(self, document, line, col, fuzzy, project=None):
        self.document = document
        self.line = line
        self.col = col
        self.fuzzy = fuzzy
        self.project = project

    def run(self):
        text_before = self.document.text_before(self.line, self.col)
        import_request = cursor_context.analyze_import(text_before)
        request = import_request or cursor_context.analyze(text_before)
        if request.kind in (cursor_context.NONE, cursor_context.IMPORT_NOTHING):
            return []

        importer = Importer(os.path.abspath(self.project or self.document.directory))
        tree = parse_tolerant(self.document.text, cursor=(self.line, self.col))
        module = ModuleContext(self.document.path, "__main__", tree, self.document.text)
        importer.register(module)
        inferrer = Inferrer(importer)

        if import_request is not None:
            entries, keywords = self._import_entries(inferrer, module, import_request)
        elif request.kind == cursor_context.ATTRIBUTE:
            scope = find_scope(module, self.line, self.col, self.document.lines[self.line - 1])
            entries = self._attribute_entries(inferrer, scope, request.receiver)
            keywords = []
        else:
            scope = find_scope(module, self.line, self.col, self.document.lines[self.line - 1])
            entries = inferrer.visible_entries(scope, self.line)
            keywords = KEYWORDS
        return self._results(entries, keywords, request.prefix)

    def _results(self, entries, keywords, prefix):
        matches = make_matcher(prefix, self.fuzzy)
        cut = len(prefix)
        results = []
        for name in sort_names(n for n in entries if matches(n)):
            kind, description = entries[name].describe(name)
            results.append(Completion(name, name[cut:], kind, description))
        for name in sort_keywords(k for k in keywords if matches(k)):
            kind, description = describe_keyword(name)
            results.append(Completion(name, name[cut:], kind, description))
        return results

    def _import_entries(self, inferrer, context, request):
        """(entries, keywords) for a cursor inside an import statement."""
        importer = inferrer.importer
        if request.kind == cursor_context.IMPORT_KEYWORD:
            return {}, ["import"]
        if request.kind == cursor_context.IMPORT_MODULE:
            if request.level:
                package = importer.import_relative(context, request.module, request.level)
                names = importer.submodule_names(package)
            elif request.module:
                names = importer.submodule_names(importer.import_absolute(request.module))
            else:
                names = importer.top_level_names()
            return {name: ModuleEntry() for name in names}, []
        source = importer.import_module(context, request.module, request.level)
        if source is None or source.kind != MODULE:
            return {}, []
        return inferrer.members.exported(source, submodules=True), []

    def _attribute_entries(self, inferrer, scope, receiver):
        try:
            expression = ast.parse(receiver.strip(), mode="eval").body
        except (SyntaxError, ValueError):
            return {}
        line_text = self.document.lines[self.line - 1]
        position = (self.line, len(line_text[:self.col].encode("utf-8")))
        entries = {}
        for value in inferrer.infer_values(expression, scope, pos=position, strict=True):
            members = inferrer.members.all(value)
            if value.kind == MODULE:
                members = {name: entry for name, entry in members.items() if is_public(name)}
            for name, entry in members.items():
                entries.setdefault(name, entry)
        return entries
"""Exception types used across sith."""


class SithError(Exception):
    """A user-facing error: reported on STDERR and turned into exit code 1."""
"""Prefix and fuzzy matching of completion names."""


def prefix_match(prefix, name):
    return name.lower().startswith(prefix.lower())


def fuzzy_match(query, name):
    """True when the characters of `query` appear in `name` in order."""
    remaining = iter(name.lower())
    return all(char in remaining for char in query.lower())


def make_matcher(prefix, fuzzy):
    if not prefix:
        return lambda name: True
    if fuzzy:
        return lambda name: fuzzy_match(prefix, name)
    return lambda name: prefix_match(prefix, name)
"""Ordering of completion results."""


def name_group(name):
    """0 for public names, 1 for private (`_x`), 2 for dunders (`__x__`)."""
    if name.startswith("__") and name.endswith("__"):
        return 2
    if name.startswith("_"):
        return 1
    return 0


def sort_names(names):
    return sorted(names, key=lambda name: (name_group(name), name.lower(), name))


def sort_keywords(keywords):
    return sorted(keywords, key=lambda name: (name.lower(), name))
"""Loading source documents and validating cursor positions."""
import os
from dataclasses import dataclass, field

from .errors import SithError


@dataclass
class Document:
    """A source file split into lines, with cursor-related helpers."""

    path: str
    text: str
    lines: list = field(default_factory=list)

    @property
    def directory(self):
        return os.path.dirname(os.path.abspath(self.path))

    def check_position(self, line, col):
        """Validate a 1-based line and 0-based column."""
        if line < 1 or line > len(self.lines):
            raise SithError(f"line {line} is out of range (file has {len(self.lines)} lines)")
        length = len(self.lines[line - 1])
        if col < 0 or col > length:
            raise SithError(f"column {col} is out of range (line {line} has {length} characters)")

    def text_before(self, line, col):
        """All source text preceding the cursor."""
        return "\n".join(self.lines[: line - 1] + [self.lines[line - 1][:col]])


def normalize_newlines(text):
    return text.replace("\r\n", "\n").replace("\r", "\n")


def read_text(path):
    """Read a file as UTF-8 text, raising SithError on any problem."""
    if not os.path.exists(path):
        raise SithError(f"file not found: {path}")
    if not os.path.isfile(path):
        raise SithError(f"not a regular file: {path}")
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except OSError as exc:
        raise SithError(f"cannot read {path}: {exc}") from exc
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise SithError(f"file is not valid UTF-8: {path}") from exc
    if text.startswith("\ufeff"):
        text = text[1:]
    return normalize_newlines(text)


def load_document(path):
    text = read_text(path)
    return Document(path=path, text=text, lines=text.split("\n"))

"""Module contexts and import resolution (project files first, then the standard library)."""
import ast
import contextlib
import importlib
import importlib.util
import io
import os
import pkgutil
import sys
import warnings

from .parsing import parse_tolerant
from .scopes import ScopeBuilder
from .source import read_text
from .errors import SithError
from .values import LocalModule, RuntimeModule

STDLIB_NAMES = frozenset(sys.stdlib_module_names) | frozenset(sys.builtin_module_names)
# Directory (relative to the project root) holding stub files for project or external modules.
STUB_DIRECTORY = "stubs"


class ModuleContext:
    """A parsed Python module together with its scope tree.

    A namespace package (a directory without `__init__.py`) is a context
    without a path and with an empty syntax tree.
    """

    def __init__(self, path, name, tree, text="", directory=None):
        self.path = os.path.abspath(path) if path else None
        if directory is not None:
            self.directory = os.path.abspath(directory)
        else:
            self.directory = os.path.dirname(self.path) if self.path else os.getcwd()
        self.name = name
        self.tree = tree
        self.text = text
        self.lines = text.split("\n")
        builder = ScopeBuilder(self)
        self.root = builder.build(tree)
        self.scope_by_node = builder.scope_by_node
        self.binding_by_target = builder.binding_by_target

    @property
    def is_namespace(self):
        return self.path is None

    @property
    def is_package(self):
        return self.is_namespace or os.path.basename(self.path) in ("__init__.py", "__init__.pyi")

    @property
    def is_stub(self):
        """True for a `.pyi` type stub."""
        return bool(self.path) and self.path.endswith(".pyi")

    @property
    def location(self):
        """The file of the module, or the directory of a namespace package."""
        return self.path or self.directory

    def scope_of(self, node):
        return self.scope_by_node.get(id(node))

    def binding_of(self, node):
        """The binding created for a name node (or def/class/except node), if any."""
        return self.binding_by_target.get(id(node))


class Importer:
    """Resolves module names to values: project files first, then the standard library.

    Anything else (third-party packages, missing modules) is unresolvable.
    """

    def __init__(self, project_dir):
        self.project_dir = os.path.abspath(project_dir)
        self.stub_dir = os.path.join(self.project_dir, STUB_DIRECTORY)
        self._contexts = {}
        self._namespaces = {}
        self._runtime = {}
        self._stubs = {}
        self._sources = {}

    def register(self, context):
        if context.path:
            self._contexts[context.path] = context

    def module_name(self, location):
        """Dotted name of the module at `location` (file or directory), relative to the root.

        Stubs in the project's stub directory are named relative to that directory.
        """
        base = self.project_dir
        if _within(location, self.stub_dir) and (location.endswith(".pyi") or os.path.isdir(location)):
            base = self.stub_dir
        try:
            relative = os.path.relpath(os.path.abspath(location), base)
        except ValueError:  # another drive (Windows)
            relative = os.pardir
        if relative == os.curdir:
            return ""
        if relative == os.pardir or relative.startswith(os.pardir + os.sep):
            relative = os.path.basename(location)
        stem = os.path.splitext(relative)[0] if os.path.isfile(location) else relative
        parts = [p for p in stem.split(os.sep) if p]
        if parts and parts[-1] == "__init__":
            parts.pop()
        return ".".join(parts)

    def context_for_file(self, path, name=None):
        path = os.path.abspath(path)
        if path not in self._contexts:
            try:
                text = read_text(path)
            except SithError:
                return None
            if name is None:
                name = self.module_name(path)
            self._contexts[path] = ModuleContext(path, name, parse_tolerant(text), text)
        return self._contexts[path]

    def namespace_for(self, directory):
        directory = os.path.abspath(directory)
        if directory not in self._namespaces:
            self._namespaces[directory] = ModuleContext(
                None, self.module_name(directory), ast.Module(body=[], type_ignores=[]),
                directory=directory)
        return self._namespaces[directory]

    def _local(self, found):
        """A LocalModule for a `_locate` result."""
        if found is None:
            return None
        kind, location = found
        if kind == "namespace":
            return LocalModule(self.namespace_for(location))
        context = self.context_for_file(location)
        return LocalModule(context) if context else None

    # -- absolute and relative imports -------------------------------------------

    def import_absolute(self, dotted):
        """Resolve `import dotted` to a module value, or None."""
        if not dotted:
            return None
        parts = dotted.split(".")
        module = self.top_level(parts[0])
        if isinstance(module, RuntimeModule) and len(parts) > 1:
            return self._import_runtime(dotted)
        for part in parts[1:]:
            if module is None:
                return None
            module = self.submodule(module, part)
        return module

    def top_level(self, name):
        """The top-level module `name`: a project module or package, else stdlib."""
        found = _locate(self.project_dir, name, namespace=False)
        if found:
            return self._local(found)
        if name in STDLIB_NAMES:
            module = self._import_runtime(name)
            if module is not None:
                return module
        found = _locate(self.stub_dir, name, namespace=False)
        if found:
            return self._local(found)
        return self._local(_locate(self.project_dir, name, namespace=True))

    def submodule(self, module, name):
        """The submodule `name` of a package value, or None."""
        if isinstance(module, LocalModule):
            return self.local_submodule(module, name)
        if isinstance(module, RuntimeModule):
            return self.runtime_submodule(module, name)
        return None

    def import_relative(self, context, dotted, level):
        """Resolve `from <level dots><dotted> import ...` relative to `context`."""
        base = context.directory
        for _ in range(level - 1):
            base = os.path.dirname(base)
        if not self.within_project(base):
            return None
        module = self.package_at(base)
        for part in (dotted.split(".") if dotted else []):
            if module is None:
                return None
            module = self.local_submodule(module, part)
        return module

    def import_module(self, context, dotted, level=0):
        if level:
            return self.import_relative(context, dotted, level)
        return self.import_absolute(dotted)

    def within_project(self, directory):
        return _within(directory, self.project_dir)

    # -- stubs ----------------------------------------------------------------------

    def stub_for(self, context):
        """The parsed `.pyi` stub giving type information for the module `context`, or None.

        An adjacent `foo.pyi` wins over `stubs/foo.pyi` and `stubs/foo/__init__.pyi`.
        """
        if context is None or not context.path or context.is_stub:
            return None
        if context.path not in self._stubs:
            self._stubs[context.path] = None
            path = self._stub_path(context.path)
            stub = self.context_for_file(path) if path else None
            if stub is not None:
                self._sources.setdefault(stub.path, context)
            self._stubs[context.path] = stub
        return self._stubs[context.path]

    def _stub_path(self, path):
        adjacent = os.path.splitext(path)[0] + ".pyi"
        if os.path.isfile(adjacent):
            return adjacent
        name = self.module_name(path)
        if not name:
            return None
        base = os.path.join(self.stub_dir, *name.split("."))
        for candidate in (base + ".pyi", os.path.join(base, "__init__.pyi")):
            if os.path.isfile(candidate):
                return candidate
        return None

    def source_for(self, stub):
        """The `.py` module a stub describes, or None for stub-only modules."""
        if stub is None or not stub.is_stub:
            return None
        if stub.path not in self._sources:
            self._sources[stub.path] = None
            path = os.path.splitext(stub.path)[0] + ".py"
            if not os.path.isfile(path):
                path = None
                if _within(stub.path, self.stub_dir):
                    path = self._source_path(self.module_name(stub.path))
            source = self.context_for_file(path) if path else None
            if source is not None and self.stub_for(source) is not stub:
                source = None
            self._sources[stub.path] = source
        return self._sources[stub.path]

    def _source_path(self, dotted):
        if not dotted:
            return None
        base = os.path.join(self.project_dir, *dotted.split("."))
        for candidate in (os.path.join(base, "__init__.py"), base + ".py"):
            if os.path.isfile(candidate):
                return candidate
        return None

    def package_at(self, directory):
        """The package whose directory is `directory` (regular or namespace)."""
        init = _package_init(directory)
        if init:
            context = self.context_for_file(init)
            return LocalModule(context) if context else None
        if os.path.isdir(directory):
            return LocalModule(self.namespace_for(directory))
        return None

    def local_submodule(self, module_value, name):
        """A submodule `name` of a local package, if such a file or directory exists."""
        context = module_value.context
        if not context.is_package or not name:
            return None
        found = _locate(context.directory, name, namespace=False)
        return self._local(found or _locate(context.directory, name, namespace=True))

    def runtime_submodule(self, module_value, name):
        if not hasattr(module_value.obj, "__path__"):
            return None
        return self._import_runtime(f"{module_value.obj.__name__}.{name}")

    # -- listing modules (import completion) ------------------------------------

    def top_level_names(self):
        """Names of every importable top-level module."""
        return set(_module_names(self.project_dir)) | set(_module_names(self.stub_dir)) | available_stdlib()

    def submodule_names(self, module):
        """Names of the submodules of a package value."""
        if isinstance(module, LocalModule):
            if not module.context.is_package:
                return set()
            return set(_module_names(module.context.directory))
        if isinstance(module, RuntimeModule):
            paths = getattr(module.obj, "__path__", None)
            if paths is None:
                return set()
            try:
                return {info.name for info in pkgutil.iter_modules(list(paths))}
            except Exception:
                return set()
        return set()

    def _import_runtime(self, dotted):
        if dotted.split(".")[0] not in STDLIB_NAMES:
            return None
        if dotted not in self._runtime:
            module = None
            try:
                with warnings.catch_warnings(), contextlib.redirect_stdout(io.StringIO()):
                    warnings.simplefilter("ignore")
                    module = importlib.import_module(dotted)
            except BaseException:  # importing arbitrary modules may fail in any way
                module = None
            self._runtime[dotted] = RuntimeModule(module) if module is not None else None
        return self._runtime[dotted]


_STDLIB_AVAILABLE = None


def _within(path, directory):
    path = os.path.abspath(path)
    directory = os.path.abspath(directory)
    return path == directory or path.startswith(directory.rstrip(os.sep) + os.sep)


def available_stdlib():
    """Top-level standard library modules that exist in this runtime."""
    global _STDLIB_AVAILABLE
    if _STDLIB_AVAILABLE is None:
        names = set()
        for name in STDLIB_NAMES:
            if name == "__main__":
                continue
            try:
                if name in sys.modules or importlib.util.find_spec(name) is not None:
                    names.add(name)
            except Exception:
                continue
        _STDLIB_AVAILABLE = names
    return _STDLIB_AVAILABLE


def _locate(directory, name, namespace):
    """("file", path) or ("namespace", directory) for module `name` inside `directory`.

    Regular packages win over modules, and source modules over stub-only
    modules; namespace packages are only considered when `namespace` is true.
    """
    if not name or not os.path.isdir(directory):
        return None
    candidate = os.path.join(directory, name)
    if namespace:
        if os.path.isdir(candidate) and name.isidentifier():
            return "namespace", candidate
        return None
    init = _package_init(candidate)
    if init:
        return "file", init
    for suffix in (".py", ".pyi"):
        if os.path.isfile(candidate + suffix):
            return "file", candidate + suffix
    return None


def _module_names(directory):
    """Names of the modules and packages (including namespace packages) in `directory`."""
    try:
        entries = os.listdir(directory)
    except OSError:
        return []
    names = []
    for entry in entries:
        path = os.path.join(directory, entry)
        if entry.endswith((".py", ".pyi")) and os.path.isfile(path):
            stem = os.path.splitext(entry)[0]
            if stem.isidentifier() and stem != "__init__":
                names.append(stem)
        elif os.path.isdir(path) and entry.isidentifier() and entry != "__pycache__":
            names.append(entry)
    return names


def _package_init(directory):
    for name in ("__init__.py", "__init__.pyi"):
        init = os.path.join(directory, name)
        if os.path.isfile(init):
            return init
    return None
"""Textual analysis of the cursor position: prefix and completion kind."""
import re
from dataclasses import dataclass

NAME = "name"
ATTRIBUTE = "attribute"
NONE = "none"

_OPENERS = {")": "(", "]": "[", "}": "{"}
_STRING_PREFIX_CHARS = "rRbBuUfF"


@dataclass
class CursorContext:
    """What kind of completion is requested and what has been typed so far."""

    kind: str
    prefix: str = ""
    receiver: str = ""


def is_identifier_char(char):
    return char == "_" or char.isalnum()


def analyze(text_before_cursor):
    """Classify the completion request from the source text before the cursor."""
    end = len(text_before_cursor)
    start = end
    while start > 0 and is_identifier_char(text_before_cursor[start - 1]):
        start -= 1
    prefix = text_before_cursor[start:]
    if prefix and prefix[0].isdigit():
        return CursorContext(NONE, prefix)

    before = text_before_cursor[:start]
    if not before.endswith("."):
        return CursorContext(NAME, prefix)

    receiver = extract_receiver(before[:-1])
    if not receiver or receiver.isdigit() or receiver.endswith("."):
        return CursorContext(NONE, prefix)
    return CursorContext(ATTRIBUTE, prefix, receiver)


def extract_receiver(text):
    """Return the expression text that ends at the end of `text`, or None."""
    i = len(text)
    while i > 0:
        char = text[i - 1]
        if char in _OPENERS:
            opener = _match_open(text, i - 1)
            if opener is None:
                return None
            i = opener
            continue
        if is_identifier_char(char):
            while i > 0 and is_identifier_char(text[i - 1]):
                i -= 1
            if i > 0 and text[i - 1] == ".":
                i -= 1
                continue
            break
        if char in "\"'":
            start = _string_start(text, i - 1)
            if start is None:
                return None
            i = start
            while i > 0 and text[i - 1] in _STRING_PREFIX_CHARS:
                i -= 1
            break
        break
    return text[i:].strip()


def _match_open(text, close_index):
    """Index of the bracket opening the one at `close_index`, scanning backwards."""
    stack = [text[close_index]]
    i = close_index - 1
    while i >= 0:
        char = text[i]
        if char in "\"'":
            start = _string_start(text, i)
            if start is None:
                return None
            i = start - 1
            continue
        if char in _OPENERS:
            stack.append(char)
        elif char in "([{":
            if _OPENERS[stack[-1]] != char:
                return None
            stack.pop()
            if not stack:
                return i
        i -= 1
    return None


def _string_start(text, end_index):
    """Index of the opening quote of the string literal ending at `end_index`."""
    quote = text[end_index]
    if end_index >= 2 and text[end_index - 2:end_index + 1] == quote * 3:
        start = text.rfind(quote * 3, 0, end_index - 2)
        return None if start < 0 else start
    i = end_index - 1
    while i >= 0:
        if text[i] == quote and (i == 0 or text[i - 1] != "\\"):
            return i
        if text[i] == "\n":
            return None
        i -= 1
    return None


# -- import statements --------------------------------------------------------------

IMPORT_MODULE = "import-module"
IMPORT_NAME = "import-name"
IMPORT_KEYWORD = "import-keyword"
IMPORT_NOTHING = "import-nothing"

_STATEMENT_START = re.compile(r"\s*(?:from|import)\b")
_DOTTED = r"((?:\w+\s*\.\s*)*)(\w*)"
_IMPORT = re.compile(r"\s*import\s+(.*)", re.S)
_FROM = re.compile(r"\s*from\s+(.*)", re.S)
_FROM_NAMES = re.compile(r"(\.*)\s*([\w.\s]*?)\s*\bimport\s+(.*)", re.S)
_FROM_KEYWORD = re.compile(r"(\.*)\s*(\w+(?:\s*\.\s*\w+)*|)\s+(\w*)", re.S)
_FROM_MODULE = re.compile(r"(\.*)\s*" + _DOTTED, re.S)
_ITEM = re.compile(_DOTTED, re.S)
_NAME = re.compile(r"(\w*)")


@dataclass
class ImportContext:
    """A cursor inside an import statement.

    `module` is the dotted module (relative to `level` leading dots) whose
    submodules or names are completed; `prefix` is what has been typed.
    """

    kind: str
    prefix: str = ""
    module: str = ""
    level: int = 0


def analyze_import(text_before_cursor):
    """An ImportContext when the cursor is inside an import statement, else None."""
    statement = _import_statement(text_before_cursor)
    if statement is None:
        return None
    if re.fullmatch(r"\s*(?:import|from)", statement):
        return None  # still typing the keyword itself
    match = _IMPORT.fullmatch(statement)
    if match:
        item = match.group(1).split(",")[-1].lstrip()
        found = _ITEM.fullmatch(item)
        if not found:
            return ImportContext(IMPORT_NOTHING)
        return ImportContext(IMPORT_MODULE, found.group(2), _dotted(found.group(1)))
    match = _FROM.fullmatch(statement)
    if not match:
        return ImportContext(IMPORT_NOTHING)
    rest = match.group(1)
    found = _FROM_NAMES.fullmatch(rest)
    if found and (found.group(1) or found.group(2).strip()):
        module = re.sub(r"\s+", "", found.group(2))
        item = found.group(3).split(",")[-1].strip()
        name = _NAME.fullmatch(item)
        if not name or not (module.replace(".", "").isidentifier() or not module):
            return ImportContext(IMPORT_NOTHING)
        return ImportContext(IMPORT_NAME, name.group(1), module, len(found.group(1)))
    found = _FROM_KEYWORD.fullmatch(rest)
    if found and (found.group(1) or found.group(2)):
        return ImportContext(IMPORT_KEYWORD, found.group(3))
    found = _FROM_MODULE.fullmatch(rest)
    if found:
        return ImportContext(IMPORT_MODULE, found.group(3), _dotted(found.group(2)),
                             len(found.group(1)))
    return ImportContext(IMPORT_NOTHING)


def _dotted(text):
    """`a . b .` -> `a.b`."""
    return ".".join(part for part in re.sub(r"\s+", "", text).split(".") if part)


def _import_statement(text):
    """The text of the import statement the cursor is in, joined onto one line, or None."""
    lines = text.split("\n")
    current = len(lines) - 1
    lines[current] = _last_simple_statement(lines[current])
    for start in range(current, max(-1, current - 100), -1):
        if _STATEMENT_START.match(lines[start]):
            if not _continues(lines[start:current]):
                return None
            joined = " ".join(_code(line).rstrip().rstrip("\\") for line in lines[start:current])
            joined = (joined + " " + lines[current]) if start < current else lines[current]
            return joined.replace("(", " ").replace(")", " ")
    return None


def _code(line):
    """`line` without a trailing comment."""
    quote = None
    for index, char in enumerate(line):
        if quote:
            if char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char == "#":
            return line[:index]
    return line


def _last_simple_statement(line):
    """The part of `line` after its last top-level `;`."""
    depth = 0
    quote = None
    start = 0
    for index, char in enumerate(line):
        if quote:
            if char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char in "([{":
            depth += 1
        elif char in ")]}":
            depth -= 1
        elif char == ";" and depth <= 0:
            start = index + 1
    return line[start:]


def _continues(lines):
    """True when each of `lines` continues onto the next (open bracket or backslash)."""
    depth = 0
    for line in lines:
        code = _code(line)
        depth += code.count("(") - code.count(")")
        if depth <= 0 and not code.rstrip().endswith("\\"):
            return False
    return True

"""The `infer` and `goto` commands: what a name evaluates to, and where it is defined."""
import ast
import keyword
import os
import re
from dataclasses import dataclass, field

from . import context as cursor_context
from .definitions import DefinitionFactory, char_column, find_word, sorted_unique
from .errors import SithError
from .inference import Inferrer, RuntimeInstance
from .locate import find_scope
from .modules import Importer, ModuleContext
from .parsing import parse_tolerant, strip_comment
from .source import load_document
from .scopes import Binding
from .values import LocalClass, LocalFunction, LocalInstance, LocalModule, unique

INFER = "infer"
GOTO = "goto"


@dataclass
class Occurrence:
    """An identifier in the source and the role it plays there."""

    kind: str
    name: str
    start: int
    end: int
    node: ast.AST = None
    extra: dict = field(default_factory=dict)


def navigate(command, path, line, col, project=None, follow_imports=False):
    """Definitions for `command` ("infer" or "goto") at the cursor in `path`.

    With `follow_imports`, `goto` follows import statements to the
    definitions they import.
    """
    document = load_document(path)
    document.check_position(line, col)
    root = os.path.abspath(project or document.directory)
    importer = Importer(root)
    tree = parse_tolerant(document.text)
    context = ModuleContext(document.path, "__main__", tree, document.text)
    importer.register(context)
    inferrer = Inferrer(importer)
    navigator = Navigator(context, inferrer, DefinitionFactory(inferrer, root), line, col)
    occurrence = navigator.occurrence()
    if occurrence is None:
        raise SithError(f"no name at line {line}, column {col}")
    if command == GOTO:
        sources = navigator.goto(occurrence)
        if follow_imports:
            sources = navigator.follow_imports(sources)
    else:
        sources = navigator.infer(occurrence)
    factory = navigator.factory
    return sorted_unique(factory.from_source(source) for source in sources)


class Navigator:
    def __init__(self, context, inferrer, factory, line=1, col=0):
        self.context = context
        self.inferrer = inferrer
        self.factory = factory
        self.parents = {}
        # Nodes starting or ending on each line, in `ast.walk` order.
        self.nodes_by_line = {}
        for parent in ast.walk(context.tree):
            for number in {getattr(parent, "lineno", None), getattr(parent, "end_lineno", None)}:
                if number is not None:
                    self.nodes_by_line.setdefault(number, []).append(parent)
            for child in ast.iter_child_nodes(parent):
                self.parents[id(child)] = parent
        self.at(line, col)

    def at(self, line, col):
        """Move the cursor to 1-based `line`, 0-based character `col`."""
        self.line = line
        self.col = col
        self.text = self.context.lines[line - 1] if 0 < line <= len(self.context.lines) else ""
        return self

    # -- locating the identifier under the cursor ---------------------------------

    def occurrence(self):
        candidates = list(self._occurrences())
        inside = [o for o in candidates if o.start <= self.col < o.end]
        touching = [o for o in candidates if o.start <= self.col <= o.end]
        for group in (inside, touching):
            if group:
                return min(group, key=lambda o: o.end - o.start)
        return self._textual_occurrence()

    def _char(self, byte_col):
        return char_column(self.context, self.line, byte_col)

    def occurrences(self):
        """Every identifier occurrence on the cursor line."""
        return list(self._occurrences())

    def _occurrences(self):
        line = self.line
        for node in self.nodes_by_line.get(line, []):
            if isinstance(node, ast.Name):
                if node.lineno == line == node.end_lineno:
                    yield Occurrence("name", node.id, self._char(node.col_offset),
                                     self._char(node.end_col_offset), node)
            elif isinstance(node, ast.Attribute):
                if node.end_lineno == line:
                    end = self._char(node.end_col_offset)
                    start = end - len(node.attr)
                    if self.text[start:end] == node.attr:
                        yield Occurrence("attr", node.attr, start, end, node)
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                if node.lineno == line:
                    match = re.compile(r"(?:async\s+)?(?:def|class)\s+").match(
                        self.text, self._char(node.col_offset))
                    if match and self.text.startswith(node.name, match.end()):
                        yield Occurrence("def", node.name, match.end(),
                                         match.end() + len(node.name), node)
            elif isinstance(node, ast.arg):
                if node.lineno == line:
                    start = self._char(node.col_offset)
                    yield Occurrence("param", node.arg, start, start + len(node.arg), node)
            elif isinstance(node, ast.alias):
                yield from self._alias_occurrences(node)
            elif isinstance(node, ast.ImportFrom):
                yield from self._import_from_module(node)
            elif isinstance(node, ast.keyword):
                if node.arg is not None and node.lineno == line:
                    start = self._char(node.col_offset)
                    yield Occurrence("kwarg", node.arg, start, start + len(node.arg), node,
                                     {"call": self.parents.get(id(node))})
            elif isinstance(node, ast.ExceptHandler):
                if node.name and node.lineno == line:
                    match = re.search(r"\bas\s+(" + re.escape(node.name) + r")\b", self.text)
                    if match:
                        yield Occurrence("bound", node.name, match.start(1), match.end(1), node)
            elif isinstance(node, (ast.MatchAs, ast.MatchStar, ast.MatchMapping)):
                name = getattr(node, "name", None) or getattr(node, "rest", None)
                if name and node.end_lineno == line:
                    end = self._char(node.end_col_offset)
                    start = self.text.rfind(name, 0, end)
                    if start >= 0:
                        yield Occurrence("bound", name, start, start + len(name), node)
            elif isinstance(node, (ast.Global, ast.Nonlocal)):
                if node.lineno == line:
                    position = self._char(node.col_offset)
                    for name in node.names:
                        found = find_word(self.text, name, position + 1)
                        if found is not None:
                            position = found
                            yield Occurrence("name", name, found, found + len(name), node)
            elif isinstance(node, ast.Constant):
                if node.value is None or isinstance(node.value, bool):
                    if node.lineno == line == node.end_lineno:
                        yield Occurrence("constant", repr(node.value), self._char(node.col_offset),
                                         self._char(node.end_col_offset), node)

    def _alias_occurrences(self, alias):
        if alias.lineno != self.line or alias.name == "*":
            return
        statement = self.parents.get(id(alias))
        start = self._char(alias.col_offset)
        if isinstance(statement, ast.Import):
            position = start
            parts = alias.name.split(".")
            for index, part in enumerate(parts):
                found = self.text.find(part, position)
                if found < 0:
                    break
                if index == 0 and not alias.asname:
                    yield Occurrence("bound", part, found, found + len(part), alias)
                else:
                    yield Occurrence("module", part, found, found + len(part), alias,
                                     {"module": ".".join(parts[:index + 1]), "level": 0})
                position = found + len(part)
        elif isinstance(statement, ast.ImportFrom):
            if alias.asname:
                yield Occurrence("imported", alias.name, start, start + len(alias.name), alias,
                                 {"statement": statement})
        else:
            return
        if isinstance(statement, ast.ImportFrom) and not alias.asname:
            yield Occurrence("bound", alias.name, start, start + len(alias.name), alias)
        if alias.asname:
            found = find_word(self.text, alias.asname, start + len(alias.name))
            if found is not None:
                yield Occurrence("bound", alias.asname, found, found + len(alias.asname), alias)

    def _import_from_module(self, node):
        if node.lineno != self.line:
            return
        match = re.compile(r"from\s+(\.*)\s*([\w.]*)").match(self.text, self._char(node.col_offset))
        if not match or not match.group(2):
            return
        position = match.start(2)
        parts = match.group(2).split(".")
        for index, part in enumerate(parts):
            yield Occurrence("module", part, position, position + len(part), node,
                             {"module": ".".join(parts[:index + 1]), "level": node.level})
            position += len(part) + 1

    def _textual_occurrence(self):
        """An identifier the parser lost (e.g. on a repaired line), if any."""
        text = self.text
        if self.col > len(strip_comment(text)) or self._in_string():
            return None
        start = end = self.col
        while start > 0 and cursor_context.is_identifier_char(text[start - 1]):
            start -= 1
        while end < len(text) and cursor_context.is_identifier_char(text[end]):
            end += 1
        word = text[start:end]
        if not word or word[0].isdigit() or keyword.iskeyword(word) or not word.isidentifier():
            return None
        receiver = None
        if text[:start].rstrip().endswith("."):
            before = "\n".join(self.context.lines[:self.line - 1] + [text[:start].rstrip()[:-1]])
            receiver = cursor_context.extract_receiver(before)
            if not receiver:
                return None
        return Occurrence("text", word, start, end, None, {"receiver": receiver})

    def _in_string(self):
        for node in ast.walk(self.context.tree):
            if isinstance(node, ast.Constant) and isinstance(node.value, (str, bytes)):
                start = (node.lineno, self._char(node.col_offset) if node.lineno == self.line else -1)
                end = (node.end_lineno, self._char(node.end_col_offset)
                       if node.end_lineno == self.line else 1 << 30)
                if start <= (self.line, self.col) < end:
                    return True
        return False

    # -- resolution ----------------------------------------------------------------

    def scope(self):
        return find_scope(self.context, self.line, self.col, self.text)

    def _byte_position(self, col):
        return (self.line, len(self.text[:col].encode("utf-8")))

    def goto(self, occurrence):
        """Bindings (or values, for runtime objects) defining the name at the cursor."""
        handler = getattr(self, "_goto_" + occurrence.kind)
        return handler(occurrence)

    def follow_imports(self, sources):
        """Replace import bindings among `sources` by the definitions they import.

        An import whose chain ends outside the project (stdlib, third-party or
        missing modules) is kept as it is: the import site is the fallback.
        """
        result = []
        for source in sources:
            followed = self._follow(source, set()) if _is_import(source) else None
            result += followed or [source]
        return result

    def _follow(self, binding, seen):
        """Definitions at the end of the import chain starting at `binding` ([] if unresolvable)."""
        if id(binding) in seen:
            return []
        seen.add(id(binding))
        importer = self.inferrer.importer
        if binding.kind == "import":
            module = importer.import_absolute(binding.extra.get("module", ""))
            return [module] if isinstance(module, LocalModule) else []
        context = binding.scope.module
        base = importer.import_module(context, binding.extra.get("module", ""),
                                      binding.extra.get("level", 0))
        if not isinstance(base, LocalModule):
            return []
        name = binding.extra.get("attribute", binding.name)
        root = base.context.root
        if not self.inferrer.binds(root, name):
            stub = self.inferrer.stubs.stub_scope(root)
            if stub is not None and self.inferrer.binds(stub, name):
                root = stub
            else:
                submodule = importer.local_submodule(base, name)
                return [submodule] if submodule is not None else []
        result = []
        for fact in self.inferrer.scope_facts(root, name):
            target = fact.binding
            if _is_import(target):
                result += self._follow(target, seen)
            else:
                result.append(target)
        return result

    def infer(self, occurrence):
        """Values the name at the cursor evaluates to."""
        handler = getattr(self, "_infer_" + occurrence.kind)
        return unique(handler(occurrence))

    # names

    def _name_facts(self, occurrence):
        node = occurrence.node
        position = (node.lineno, node.col_offset) if isinstance(node, ast.Name) else \
            self._byte_position(occurrence.start)
        return self.inferrer.name_facts(occurrence.name, self.scope(), position)

    def _store_binding(self, occurrence):
        node = occurrence.node
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            binding = self.context.binding_of(node)
            if binding is not None:
                return binding
            parent = self.parents.get(id(node))
            if isinstance(parent, ast.AugAssign):
                scope = self.scope()
                return self.inferrer.synthetic_binding(scope)("aug", parent, node.id)
        return None

    def _goto_name(self, occurrence):
        binding = self._store_binding(occurrence)
        if binding is not None:
            return [binding]
        return [fact.binding for fact in self._name_facts(occurrence)]

    def _infer_name(self, occurrence):
        binding = self._store_binding(occurrence)
        if binding is not None and binding.kind != "augassign":
            return self.inferrer.binding_values(binding)
        values = []
        for fact in self._name_facts(occurrence):
            values += self.inferrer.fact_values(fact)
        return values

    # attributes

    def _instance_attribute(self, occurrence, bases):
        """The `self.attr = ...` binding at the cursor, with the instance it belongs to."""
        node = occurrence.node
        for base in bases:
            if isinstance(base, LocalInstance):
                for cls in self.inferrer.members.mro(base.cls):
                    for binding in self.inferrer.members.instance_attribute_bindings(cls).get(
                            occurrence.name, []):
                        if binding.target is node:
                            return binding, base
        return None, None

    def _goto_attr(self, occurrence):
        node = occurrence.node
        bases = self.inferrer.infer_values(node.value, self.scope())
        if isinstance(node.ctx, ast.Store):
            binding, _ = self._instance_attribute(occurrence, bases)
            if binding is not None:
                return [binding]
        sources = []
        for base in bases:
            sources += self.inferrer.members.member_definitions(base, occurrence.name)
        return sources

    def _infer_attr(self, occurrence):
        node = occurrence.node
        bases = self.inferrer.infer_values(node.value, self.scope())
        if isinstance(node.ctx, ast.Store):
            binding, instance = self._instance_attribute(occurrence, bases)
            if binding is not None:
                return self.inferrer.members.instance_attribute_values(binding, instance)
        values = []
        for base in bases:
            values += self.inferrer.members.member_values(base, occurrence.name)
        return values

    # definitions and other bound names

    def _bound_binding(self, occurrence):
        return self.context.binding_of(occurrence.node)

    def _goto_bound(self, occurrence):
        binding = self._bound_binding(occurrence)
        return [binding] if binding is not None else []

    def _infer_bound(self, occurrence):
        binding = self._bound_binding(occurrence)
        return self.inferrer.binding_values(binding) if binding is not None else []

    _goto_def = _goto_param = _goto_bound
    _infer_def = _infer_param = _infer_bound

    # modules named in import statements

    def _module_value(self, occurrence):
        module = self.inferrer.importer.import_module(
            self.context, occurrence.extra["module"], occurrence.extra["level"])
        return [module] if module is not None else []

    _goto_module = _infer_module = _module_value

    def _goto_imported(self, occurrence):
        statement = occurrence.extra["statement"]
        base = self.inferrer.importer.import_module(self.context, statement.module or "",
                                                    statement.level)
        if base is not None:
            found = self.inferrer.members.member_definitions(base, occurrence.name)
            if found:
                return found
        return self._infer_imported(occurrence)

    def _infer_imported(self, occurrence):
        statement = occurrence.extra["statement"]
        return self.inferrer.resolve_from_values(self.context, statement.module or "",
                                                 statement.level, occurrence.name)

    # keyword arguments

    def _keyword_parameters(self, occurrence):
        call = occurrence.extra.get("call")
        if not isinstance(call, ast.Call):
            return []
        bindings = []
        for function in self.inferrer.infer_values(call.func, self.scope()):
            if isinstance(function, LocalClass):
                init = self.inferrer.members.find_method(function, "__init__")
                if init is None:
                    # Generated `__init__` (dataclasses and the like): parameters are the fields.
                    for cls in self.inferrer.members.mro(function):
                        bindings += [b for b in cls.scope.bindings.get(occurrence.name, [])
                                     if b.extra.get("annotation") is not None]
                    continue
                function = init
            elif isinstance(function, LocalInstance):
                function = self.inferrer.members.find_method(function.cls, "__call__")
            if isinstance(function, LocalFunction):
                bindings += [b for b in function.scope.bindings.get(occurrence.name, [])
                             if b.kind == "param"]
        return bindings

    def _goto_kwarg(self, occurrence):
        return self._keyword_parameters(occurrence)

    def _infer_kwarg(self, occurrence):
        values = []
        for binding in self._keyword_parameters(occurrence):
            values += self.inferrer.binding_values(binding)
        return values

    # literals

    def _goto_constant(self, occurrence):
        return []

    def _infer_constant(self, occurrence):
        return [RuntimeInstance(type(occurrence.node.value))]

    # identifiers missing from the (repaired) syntax tree

    def _text_receiver_values(self, occurrence):
        try:
            expression = ast.parse(occurrence.extra["receiver"].strip(), mode="eval").body
        except (SyntaxError, ValueError):
            return []
        return self.inferrer.infer_values(expression, self.scope(),
                                          pos=self._byte_position(occurrence.start))

    def _goto_text(self, occurrence):
        if occurrence.extra.get("receiver"):
            sources = []
            for base in self._text_receiver_values(occurrence):
                sources += self.inferrer.members.member_definitions(base, occurrence.name)
            return sources
        return [fact.binding for fact in self._name_facts(occurrence)]

    def _infer_text(self, occurrence):
        if occurrence.extra.get("receiver"):
            values = []
            for base in self._text_receiver_values(occurrence):
                values += self.inferrer.members.member_values(base, occurrence.name)
            return values
        values = []
        for fact in self._name_facts(occurrence):
            values += self.inferrer.fact_values(fact)
        return values


def _is_import(source):
    return isinstance(source, Binding) and source.kind in ("import", "importfrom")
"""Finding the innermost scope that contains the cursor."""
import ast

from .scopes import COMPREHENSION, LAMBDA

_DEFINITIONS = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)


def cursor_indent(line_text, col):
    """Indentation that governs the cursor's block membership."""
    before = line_text[:col]
    if not before.strip():
        return len(before)
    return len(line_text) - len(line_text.lstrip())


def find_scope(context, line, col, line_text):
    """The innermost Scope of `context` enclosing the cursor at (line, col)."""
    byte_col = len(line_text[:col].encode("utf-8"))
    indent = cursor_indent(line_text, col)
    scope = context.root
    for node in _definition_chain(context.tree.body, line, byte_col, indent):
        scope = context.scope_of(node) or scope
    return _innermost_expression_scope(scope, line, byte_col)


def _definition_chain(statements, line, byte_col, indent):
    """def/class nodes whose bodies contain the cursor, outermost first."""
    chain = []
    while True:
        candidate = None
        for statement in statements:
            if statement.lineno <= line:
                candidate = statement
            else:
                break
        if candidate is None:
            return chain
        inside = line <= candidate.end_lineno or indent > candidate.col_offset
        if not inside:
            return chain
        if isinstance(candidate, _DEFINITIONS):
            if not _in_body(candidate, line, byte_col):
                return chain
            chain.append(candidate)
            statements = candidate.body
        else:
            statements = _child_statements(candidate)
            if not statements:
                return chain


def _in_body(node, line, byte_col):
    first = node.body[0]
    if line > _header_end(node):
        return True
    return line == first.lineno and byte_col >= first.col_offset


def _header_end(node):
    parts = []
    if isinstance(node, ast.ClassDef):
        parts = node.bases + [k.value for k in node.keywords]
    else:
        args = node.args
        parts = args.posonlyargs + args.args + args.kwonlyargs + args.defaults
        parts += [d for d in args.kw_defaults if d is not None]
        parts += [a for a in (args.vararg, args.kwarg, node.returns) if a is not None]
    return max([node.lineno] + [getattr(p, "end_lineno", None) or node.lineno for p in parts])


def _child_statements(node):
    children = []
    for field in ("body", "orelse", "finalbody"):
        children += [s for s in getattr(node, field, []) if isinstance(s, ast.stmt)]
    for handler in getattr(node, "handlers", []):
        children += handler.body
    for case in getattr(node, "cases", []):
        children += case.body
    return sorted(children, key=lambda s: (s.lineno, s.col_offset))


def _contains(node, line, byte_col):
    start = (node.lineno, node.col_offset)
    end = (node.end_lineno, node.end_col_offset)
    return start <= (line, byte_col) <= end


def _innermost_expression_scope(scope, line, byte_col):
    """Descend into lambda/comprehension scopes that contain the cursor."""
    while True:
        for child in scope.children:
            if child.kind in (LAMBDA, COMPREHENSION) and _contains(child.node, line, byte_col):
                scope = child
                break
        else:
            return scope

"""Definition records reported by `infer` and `goto`."""
import ast
import inspect
import os
import re
import sys
from dataclasses import asdict, dataclass

from .inference import BuiltinBinding
from .scopes import CLASS, FUNCTION, Binding
from .values import (
    LocalClass,
    LocalFunction,
    LocalInstance,
    LocalModule,
    RuntimeClass,
    RuntimeFunction,
    RuntimeInstance,
    RuntimeModule,
)

_DEFINITION_HEADER = re.compile(r"(?:async\s+)?(?:def|class)\s+")


@dataclass
class Definition:
    name: str
    type: str
    full_name: str
    module_path: str
    line: int
    column: int
    description: str
    docstring: str

    def to_dict(self):
        return asdict(self)

    @property
    def sort_key(self):
        return (self.module_path, self.line, self.column)


def sorted_unique(definitions):
    """Definitions without duplicates, sorted by (module_path, line, column)."""
    seen = set()
    result = []
    for definition in definitions:
        if definition is None:
            continue
        identity = tuple(definition.to_dict().items())
        if identity not in seen:
            seen.add(identity)
            result.append(definition)
    return sorted(result, key=lambda d: d.sort_key)


def normalize(text):
    return re.sub(r"\s+", " ", text).strip()


def char_column(context, line, byte_col):
    """Convert a UTF-8 byte offset on `line` to a character offset."""
    if not 1 <= line <= len(context.lines):
        return byte_col
    encoded = context.lines[line - 1].encode("utf-8")
    return len(encoded[:byte_col].decode("utf-8", errors="ignore"))


def posix_path(path):
    return path.replace(os.sep, "/") if os.sep != "/" else path


def find_word(text, word, start=0):
    """Column of the identifier `word` in `text` at or after `start`, or None."""
    match = re.compile(r"(?<![\w])" + re.escape(word) + r"(?![\w])").search(text, max(start, 0))
    return match.start() if match else None


class DefinitionFactory:
    """Builds Definition records for bindings and inferred values."""

    def __init__(self, inferrer, project_root):
        self.inferrer = inferrer
        self.project_root = os.path.abspath(project_root)

    # -- modules and paths -----------------------------------------------------

    def relative_path(self, path):
        """`path` relative to the project root (absolute outside it), with `/` separators."""
        if not path:
            return ""
        path = os.path.abspath(path)
        try:
            relative = os.path.relpath(path, self.project_root)
        except ValueError:
            return posix_path(path)
        if relative == os.pardir or relative.startswith(os.pardir + os.sep):
            return posix_path(path)
        return posix_path(relative)

    def module_name(self, context):
        """Dotted module name of a parsed file, relative to the project root."""
        if not context.path or context.is_stub:
            return context.name
        relative = self.relative_path(context.path)
        if os.path.isabs(relative):
            if context.name and context.name != "__main__":
                return context.name
            relative = os.path.basename(relative)
        stem = os.path.splitext(relative)[0]
        parts = [p for p in stem.split("/") if p]
        if len(parts) > 1 and parts[-1] == "__init__":
            parts.pop()
        return ".".join(parts)

    def qualified_name(self, scope):
        """Dotted name of a scope: module, then enclosing classes and functions."""
        parts = []
        for current in scope.chain():
            if current.kind in (CLASS, FUNCTION):
                parts.append(current.node.name)
        parts.append(self.module_name(scope.module))
        return ".".join(reversed(parts))

    # -- source helpers --------------------------------------------------------

    @staticmethod
    def source(context, node):
        text = None
        try:
            text = ast.get_source_segment(context.text, node)
        except Exception:
            text = None
        if not text:
            try:
                text = ast.unparse(node)
            except Exception:
                text = ""
        return normalize(text)

    def parameters(self, context, arguments):
        """The parameter list of a function, formatted like its source."""

        def param(arg, default=None):
            text = arg.arg
            if arg.annotation is not None:
                text += ": " + self.source(context, arg.annotation)
            if default is not None:
                separator = " = " if arg.annotation is not None else "="
                text += separator + self.source(context, default)
            return text

        parts = []
        positional = arguments.posonlyargs + arguments.args
        defaults = [None] * (len(positional) - len(arguments.defaults)) + list(arguments.defaults)
        for index, arg in enumerate(positional):
            parts.append(param(arg, defaults[index]))
            if arguments.posonlyargs and index == len(arguments.posonlyargs) - 1:
                parts.append("/")
        if arguments.vararg is not None:
            parts.append("*" + param(arguments.vararg))
        elif arguments.kwonlyargs:
            parts.append("*")
        for arg, default in zip(arguments.kwonlyargs, arguments.kw_defaults):
            parts.append(param(arg, default))
        if arguments.kwarg is not None:
            parts.append("**" + param(arguments.kwarg))
        return ", ".join(parts)

    # -- bindings ----------------------------------------------------------------

    def from_source(self, source):
        """A Definition for a Binding, BuiltinBinding or Value."""
        if isinstance(source, BuiltinBinding):
            return self.from_value(source.value())
        if isinstance(source, Binding):
            return self.from_binding(source)
        return self.from_value(source)

    def from_binding(self, binding):
        context = binding.scope.module
        line, column = self.binding_position(binding)
        owner = binding.extra.get("owner")
        if owner is not None:
            full_name = f"{self.qualified_name(owner)}.{binding.name}"
        else:
            full_name = f"{self.qualified_name(binding.scope)}.{binding.name}"
        docstring = ""
        if binding.kind in ("def", "class"):
            docstring = ast.get_docstring(binding.node) or ""
        return Definition(
            name=binding.name,
            type=self.binding_type(binding),
            full_name=full_name,
            module_path=self.relative_path(context.path),
            line=line,
            column=column,
            description=self.binding_description(binding),
            docstring=docstring,
        )

    def binding_type(self, binding):
        kind = binding.kind
        if kind == "def":
            return "function"
        if kind == "class":
            return "class"
        if kind == "param":
            return "param"
        if kind == "import":
            return "module"
        if kind == "importfrom":
            values = self.inferrer.binding_values(binding)
            if values and values[0].kind:
                return values[0].kind
            return "module"
        return "statement"

    def binding_description(self, binding):
        context = binding.scope.module
        node = binding.node
        kind = binding.kind
        if kind == "def":
            return f"def {node.name}({self.parameters(context, node.args)})"
        if kind == "class":
            return f"class {node.name}"
        if kind == "param":
            return f"param {binding.name}"
        if kind in ("import", "importfrom"):
            return normalize(ast.unparse(node))
        if kind == "assign":
            if isinstance(node, (ast.Assign, ast.NamedExpr)) or (
                    isinstance(node, ast.AnnAssign) and node.value is not None):
                return self.source(context, node.value)
            return self.source(context, node)
        if kind in ("loop", "comprehension"):
            return f"for {self.source(context, node.target)} in {self.source(context, node.iter)}"
        if kind == "with":
            items = ", ".join(self.source(context, item) for item in node.items)
            return f"with {items}"
        if kind == "except":
            if node.type is None:
                return "except"
            return f"except {self.source(context, node.type)} as {binding.name}"
        if kind == "pattern":
            return f"case {self.source(context, node.pattern)}"
        return self.source(context, node)

    def binding_position(self, binding):
        """(1-based line, 0-based character column) of the bound identifier."""
        context = binding.scope.module
        target = binding.target
        node = binding.node
        lines = context.lines

        def text(line):
            return lines[line - 1] if 1 <= line <= len(lines) else ""

        if isinstance(target, (ast.Name, ast.arg)):
            return target.lineno, char_column(context, target.lineno, target.col_offset)
        if isinstance(target, ast.Attribute):
            end = char_column(context, target.end_lineno, target.end_col_offset)
            return target.end_lineno, end - len(target.attr)
        if isinstance(target, ast.alias):
            start = char_column(context, target.lineno, target.col_offset)
            if target.asname:
                found = find_word(text(target.lineno), target.asname, start + len(target.name))
                if found is not None:
                    return target.lineno, found
            return target.lineno, start
        if binding.kind in ("def", "class"):
            start = char_column(context, node.lineno, node.col_offset)
            match = _DEFINITION_HEADER.match(text(node.lineno), start)
            if match:
                return node.lineno, match.end()
            return node.lineno, start
        if binding.kind == "except":
            for line in range(node.lineno, (node.body[0].lineno if node.body else node.lineno) + 1):
                match = re.search(r"\bas\s+(" + re.escape(binding.name) + r")\b", text(line))
                if match:
                    return line, match.start(1)
        if isinstance(target, ast.pattern):
            for line in range(target.lineno, target.end_lineno + 1):
                start = char_column(context, line, target.col_offset) if line == target.lineno else 0
                found = find_word(text(line), binding.name, start)
                if found is not None:
                    return line, found
        if binding.kind == "importfrom" and isinstance(node, ast.ImportFrom):
            star = text(node.lineno).find("*")
            if star >= 0:
                return node.lineno, star
        found = find_word(text(binding.line), binding.name)
        return binding.line, found if found is not None else 0

    # -- values --------------------------------------------------------------------

    def from_value(self, value):
        if value is None:
            return None
        if isinstance(value, (LocalFunction, LocalClass)):
            return self._local_definition(value)
        if isinstance(value, LocalInstance):
            definition = self._local_definition(value.cls)
            if definition is None:
                return None
            definition.type = "instance"
            definition.description = f"instance of {value.cls.name}"
            return definition
        if isinstance(value, LocalModule):
            context = value.context
            name = self.module_name(context)
            return Definition(
                name=name.split(".")[-1],
                type="module",
                full_name=name,
                module_path=self.relative_path(context.location),
                line=1,
                column=0,
                description=f"module {name.split('.')[-1]}",
                docstring=ast.get_docstring(context.tree) or "",
            )
        if isinstance(value, RuntimeModule):
            return self._runtime_module(value.obj)
        if isinstance(value, RuntimeClass):
            return self._runtime_definition(value.obj, "class")
        if isinstance(value, RuntimeFunction):
            return self._runtime_definition(value.obj, "function")
        if isinstance(value, RuntimeInstance):
            return self._runtime_definition(value.cls, "instance")
        return None

    def _local_definition(self, value):
        node = value.scope.node
        context = value.scope.module
        if isinstance(node, ast.Lambda):
            parameters = self.parameters(context, node.args)
            return Definition(
                name="<lambda>",
                type="function",
                full_name=f"{self.qualified_name(value.scope.parent)}.<lambda>",
                module_path=self.relative_path(context.path),
                line=node.lineno,
                column=char_column(context, node.lineno, node.col_offset),
                description=f"def <lambda>({parameters})",
                docstring="",
            )
        binding = context.binding_of(node)
        if binding is None:
            return None
        return self.from_binding(binding)

    def _runtime_module(self, module):
        name = getattr(module, "__name__", "") or ""
        path = getattr(module, "__file__", None) or ""
        if path.endswith((".pyc", ".pyo")):
            path = path[:-1]
        if path and not path.endswith(".py"):
            path = ""
        return Definition(
            name=name.split(".")[-1],
            type="module",
            full_name=name,
            module_path=self.relative_path(path),
            line=1 if path else 0,
            column=0,
            description=f"module {name.split('.')[-1]}",
            docstring=_docstring(module),
        )

    def _runtime_definition(self, obj, kind):
        name = getattr(obj, "__name__", None) or type(obj).__name__
        qualname = getattr(obj, "__qualname__", None) or name
        module = getattr(obj, "__module__", None)
        if not isinstance(module, str):
            owner = getattr(obj, "__objclass__", None) or getattr(getattr(obj, "__self__", None), "__class__", None)
            module = getattr(owner, "__module__", None) if owner is not None else None
        module = module or "builtins"
        builtin = module == "builtins"
        path, line, column = ("", 0, 0) if builtin else _runtime_location(obj, name)
        if kind == "class":
            description = f"class {name}"
        elif kind == "instance":
            description = f"instance of {name}"
        else:
            description = f"def {name}({_runtime_parameters(obj)})"
        return Definition(
            name=name,
            type=kind,
            full_name=f"{module}.{qualname}",
            module_path=self.relative_path(path),
            line=line,
            column=column,
            description=description,
            docstring="" if builtin else _docstring(obj),
        )


def _docstring(obj):
    try:
        return inspect.getdoc(obj) or ""
    except Exception:
        return ""


def _runtime_parameters(obj):
    try:
        signature = inspect.signature(obj)
    except (TypeError, ValueError):
        return "..."
    text = str(signature.replace(return_annotation=inspect.Signature.empty))
    return text[1:-1]


def _runtime_location(obj, name):
    """(path, line, column) of a runtime class or function's source, if available."""
    path = ""
    module = sys.modules.get(getattr(obj, "__module__", None) or "")
    module_file = getattr(module, "__file__", None) or ""
    if module_file.endswith(".py"):
        path = module_file
    try:
        source_file = inspect.getsourcefile(obj)
        lines, start = inspect.getsourcelines(obj)
    except (TypeError, OSError):
        return path, 0, 0
    if not source_file:
        return path, 0, 0
    for offset, text in enumerate(lines):
        match = re.search(r"(?:def|class)\s+(" + re.escape(name) + r")\b", text)
        if match:
            return source_file, start + offset, match.start(1)
    return source_file, start, 0
"""The `signatures` command: the signature of the call surrounding the cursor."""
import ast
import inspect
import keyword
import os
import re
from dataclasses import asdict, dataclass, field

from . import context as cursor_context
from .definitions import DefinitionFactory
from .inference import Inferrer
from .locate import find_scope
from .modules import ModuleContext, Importer
from .parsing import _starts_statement, parse_tolerant
