import ast
import inspect
import os
import re
import sys
from dataclasses import asdict, dataclass

from .inference import BuiltinBinding
from .scopes import CLASS, FUNCTION, Binding
from .values import (
    LocalClass,
    LocalFunction,
    LocalInstance,
    LocalModule,
    RuntimeClass,
    RuntimeFunction,
