def declared_returns(self, function, call=None, scope=None, pos=None, strict=False,
                     offset=0, awaited=False):
    """Return values declared by a stub or overloads of `function` (None if undeclared).

    With a `call`, the first overload accepting its arguments is used.
    """
    if not isinstance(function.node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return None
    declarations = self.declarations(function.scope)
    if declarations == [function.scope]:
        return None
    chosen = declarations
    if call is not None and len(declarations) > 1:
        matching = [d for d in declarations
                    if self._accepts(d, call, scope, pos, strict, offset)]
        chosen = matching[:1] or declarations
    values = []
    for declaration in chosen:
        node = declaration.node
        if isinstance(node, ast.AsyncFunctionDef) and not awaited:
            values.append(RuntimeInstance(types.CoroutineType))
        elif node.returns is not None:
            values += self.annotation_values(node.returns, declaration.parent)
    return unique(values)

def _accepts(self, declaration, call, scope, pos, strict, offset):
    """Whether the arguments of `call` fit the parameters of a declared overload."""
    arguments = declaration.node.args
    positional = (arguments.posonlyargs + arguments.args)[offset:]
    keyword_names = {a.arg for a in arguments.args[max(0, offset - len(arguments.posonlyargs)):]}
    keyword_names |= {a.arg for a in arguments.kwonlyargs}
    provided = {}
    if any(isinstance(a, ast.Starred) for a in call.args) or any(
            k.arg is None for k in call.keywords):
        return True
    if len(call.args) > len(positional) and arguments.vararg is None:
        return False
    for index, argument in enumerate(call.args[:len(positional)]):
        provided[positional[index].arg] = (positional[index], argument)
    params = {a.arg: a for a in positional + arguments.kwonlyargs}
    for keyword in call.keywords:
        if keyword.arg in keyword_names and keyword.arg not in provided:
            provided[keyword.arg] = (params[keyword.arg], keyword.value)
        elif arguments.kwarg is None:
            return False
    defaults = len(arguments.defaults)
    required = positional[:len(positional) - defaults] if defaults else positional
    required += [a for a, d in zip(arguments.kwonlyargs, arguments.kw_defaults) if d is None]
    if any(a.arg not in provided for a in required):
        return False
    for param, argument in provided.values():
        if param.annotation is None:
            continue
        expected = self.annotation_values(param.annotation, declaration.parent)
        classes = unique(c for c in map(self.class_of, expected) if c is not None)
        actual = self.infer_values(argument, scope, pos, strict)
        if classes and actual and not any(self._compatible(v, classes) for v in actual):
            return False
    return True

def _compatible(self, value, classes):
    if self.is_instance(value, classes):
        return True
    if isinstance(value, RuntimeInstance) and value.cls in _NUMERIC_TOWER:
        index = _NUMERIC_TOWER.index(value.cls)
        return any(isinstance(c, RuntimeClass) and c.obj in _NUMERIC_TOWER[index:]
                   for c in classes)
    return False

def annotation_values(self, annotation, scope, pos=None):
    """Instances described by a type annotation."""
    if annotation is None:
        return []
    if isinstance(annotation, ast.Constant):
        if annotation.value is None:
            return [NONE]
        if isinstance(annotation.value, str):
            try:
                parsed = ast.parse(annotation.value.strip(), mode="eval").body
            except SyntaxError:
                return []
            return self.annotation_values(parsed, scope, pos or _position(annotation))
        return []
    if isinstance(annotation, ast.BinOp) and isinstance(annotation.op, ast.BitOr):
        return unique(self.annotation_values(annotation.left, scope, pos)
                      + self.annotation_values(annotation.right, scope, pos))
    if isinstance(annotation, ast.Subscript):
        arguments = annotation.slice
        arguments = arguments.elts if isinstance(arguments, ast.Tuple) else [arguments]
        special = _typing_form(annotation.value, self.infer_values(annotation.value, scope, pos))
        if special == "Optional":
            return unique(self.annotation_values(arguments[0], scope, pos) + [NONE])
        if special == "Union":
            return unique(v for a in arguments for v in self.annotation_values(a, scope, pos))
        if special in ("ClassVar", "Final", "Annotated", "Required", "NotRequired"):
            return self.annotation_values(arguments[0], scope, pos)
        if special == "Type":
            classes = self.infer_values(arguments[0], scope, pos)
            if scope.module.is_stub:
                classes = self.from_stub(classes)
            return [v for v in classes if isinstance(v, (LocalClass, RuntimeClass))]
        annotation = annotation.value
    values = self.infer_values(annotation, scope, pos)
    if scope.module.is_stub:
        values = self.from_stub(values)
    return unique(instance_of(v) for v in values if isinstance(v, (LocalClass, RuntimeClass)))

