def dynamic_param_values(self, binding):
    """Values passed for an unannotated parameter at call sites in the function's own module.

    Only used for functions without any annotation and without a stub.
    """
    scope = binding.scope
    node = scope.node
    if scope.kind != FUNCTION or scope.module.is_stub or _is_annotated(node):
        return []
    if self.stubs.function_scopes(scope):
        return []
    key = (id(node), binding.name)
    if key in self._dynamic_cache:
        return self._dynamic_cache[key]
    if key in self._active:
        return []
    self._active.add(key)
    frames, self._frames = self._frames, []
    try:
        values = []
        arg = binding.extra["arg"]
        for call, call_scope, offset in self.call_sites(scope):
            args = self.map_arguments(node, call, call_scope, None, False, offset)
            if binding.name in args:
                values += args[binding.name]
            else:
                default = _default_for(node.args, arg)
                if default is not None:
                    values += self.infer_values(default, scope.parent)
        values = unique(values)
    finally:
        self._frames = frames
        self._active.discard(key)
    self._dynamic_cache[key] = values
    return values

def call_sites(self, scope):
    """(call, scope of the call, number of implicit leading arguments) for calls of `scope`."""
    node = scope.node
    context = scope.module
    names = {node.name}
    constructor = node.name == "__init__" and scope.parent.kind == CLASS
    if constructor:
        names.add(scope.parent.node.name)
    sites = []
    for call in self._calls_named(context, names):
        call_scope = self.scope_at(context, call)
        for function in self.infer_values(call.func, call_scope):
            if isinstance(function, LocalFunction) and function.scope is scope:
                sites.append((call, call_scope, 1 if function.bound is not None else 0))
                break
            if constructor and isinstance(function, LocalClass):
                init = self.members.find_method(function, "__init__")
                if init is not None and init.scope is scope:
                    sites.append((call, call_scope, 1))
                    break
    return sites

def _calls_named(self, context, names):
    key = id(context)
    if key not in self._call_index:
        index = {}
        for candidate in ast.walk(context.tree):
            if isinstance(candidate, ast.Call):
                func = candidate.func
                name = func.attr if isinstance(func, ast.Attribute) else getattr(func, "id", None)
                if name:
                    index.setdefault(name, []).append(candidate)
        self._call_index[key] = index
    index = self._call_index[key]
    return [call for name in sorted(names) for call in index.get(name, [])]

@staticmethod
def scope_at(context, node):
    """The innermost scope of `context` containing expression `node`."""
    line = node.lineno
    text = context.lines[line - 1] if 0 < line <= len(context.lines) else ""
    col = len(text.encode("utf-8")[:node.col_offset].decode("utf-8", errors="ignore"))
    return find_scope(context, line, col, text)

