    seen = set()
    result = []
    for path in paths:
        if path not in seen:
            seen.add(path)
            result.append(path)
    return result


_CURRENT = [Options()]


def current():
    """The Options of the running command (defaults outside of the command line)."""
    return _CURRENT[-1]


@contextlib.contextmanager
def activate(options):
    _CURRENT.append(options)
    try:
        yield options
    finally:
        _CURRENT.pop()

